contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint minSumParam) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(minSumParam == 0);

        c.SetMinSum(minSumParam); if (__ESBMC_reverted()) return;

        (uint unlockTime1, uint balance1) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalanceBefore = address(c).balance;
        uint thisBalanceBefore = address(this).balance;

        c.Collect(0); if (__ESBMC_reverted()) return;

        (uint unlockTime2, uint balance2) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalanceAfter = address(c).balance;
        uint thisBalanceAfter = address(this).balance;

        assert(balance2 == balance1 &&
               contractBalanceAfter == contractBalanceBefore &&
               thisBalanceAfter == thisBalanceBefore);
    }

    receive() external payable {}
}

