pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 minSumParam) internal {
        vm.deal(address(c), VALUE_CAP);
        minSumParam = 0;
        try c.SetMinSum(minSumParam) {} catch { return; }
        uint256 unlockTime1;
        uint256 balance1;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockTime1 = __r0; balance1 = __r1; } catch { return; }
        uint contractBalanceBefore = address(c).balance;
        uint thisBalanceBefore = address(this).balance;
        try c.Collect(0) {} catch { return; }
        uint256 unlockTime2;
        uint256 balance2;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockTime2 = __r0; balance2 = __r1; } catch { return; }
        uint contractBalanceAfter = address(c).balance;
        uint thisBalanceAfter = address(this).balance;
        assertTrue(balance2 == balance1 &&
               contractBalanceAfter == contractBalanceBefore &&
               thisBalanceAfter == thisBalanceBefore);
    }

    function testFuzz_run(uint256 minSumParam) public {
        _run(minSumParam);
    }

    receive() external payable {}
}
